// === Tab: mySketch ===
// http://recodeproject.com/artwork/v1n3structure-square-series-inwards4
// self implementation

const PAD = 8;
const SZE = 50;

function setup() {
  let maxY = 0;
  for (let y = PAD + SZE / 2; y <= windowHeight - SZE - PAD; y += SZE + PAD) {
    maxY = y;
  }
  maxY += SZE / 2 + PAD;

  let maxX = 0;
  for (let x = PAD + SZE / 2; x <= windowWidth - SZE - PAD; x += SZE + PAD) {
    maxX = x
  }
  maxX += SZE / 2 + PAD;

  createCanvas(maxX, maxY);
  describe("grid of rectangles filled with lines, more complex as distance expands from center")
	frameRate(3);

  stroke("black");
  strokeWeight(2);
}

function draw() {
	background("beige");

	const spotPt = {x: width / 2, y: height / 2}; // {x: (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), y: (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))};
	const maxD = dist(PAD + SZE / 2, PAD + SZE / 2, spotPt.x, spotPt.y);
  for (let y = PAD + SZE / 2; y <= height - SZE/2 - PAD; y += SZE + PAD) {
    for (let x = PAD + SZE / 2; x <= width - SZE/2 - PAD; x += SZE + PAD) {
      drawShape(x, y, SZE, (dist(x, y, spotPt.x, spotPt.y)) / maxD);
    }
  }
}

function drawShape(x, y, s, t) {
  push();
  translate(x, y);

  const clrs = ["rgb(91,14,14)", "rgb(16,16,87)", "rgb(84,54,19)", "rgb(15,79,15)"]
  const pts = [[-0.5, -0.5], [0, -0.5], [0.5, -0.5], [0.5, 0], [0.5, 0.5], [0, 0.5], [-0.5, 0.5], [-0.5, 0]];
  const conns = [[0,4], [1,5], [2,6], [3,7], [1,3], [3,5], [5,7], [7,1]];


  const iter = ~~(t * (conns.length));
  for (let i = 0; i < iter; i++) {
    if (!(conns.length > 0)) break;
    let ci = ~~random(conns.length);
    let c = conns[ci];
    let p1 = pts[c[0]];
    let p2 = pts[c[1]];
    stroke(random(clrs));
    line(p1[0] * s, p1[1] * s, p2[0] * s, p2[1] * s);
    conns.splice(ci, 1);
  }

  rectMode(CENTER);
  noFill();
  stroke(0);
  rect(0, 0, s, s);

  pop();
}

function mousePressed() {
  if (mouseButton === LEFT) setup();
}
